                'cancel_order'=>$this->orderAction($actor,$payload,'cancel'),
                'return_order'=>$this->returnOrder($actor,$payload),
                'product'=>$this->saveProduct($actor,$payload),
                'inventory'=>$this->inventory($actor,$payload),
                'exchange'=>$this->exchange($actor,$payload),
                'glass_brand'=>$this->glassBrand($actor,$payload),
                'staff_state'=>$this->staffState($actor,$payload),
