            $this->audit($actor['id'],$action,(string)($result['id']??''));$this->pdo->prepare('UPDATE pos_mutation_requests SET result=? WHERE actor_id=? AND request_key=?')->execute([json_encode($result),$actor['id'],$key]);$this->pdo->commit();return$result;
        }catch(\Throwable$error){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$error;}
    }
    public function deleteProduct(array$actor,array$payload):array
