        $placeholders=implode(',',array_fill(0,count($seen),'?'));$this->pdo->prepare("DELETE FROM pos_sales_order_items WHERE order_id=? AND product_id NOT IN({$placeholders})")->execute([$id,...array_keys($seen)]);$s=$this->pdo->prepare('SELECT COALESCE(SUM(quantity*unit_sale_price),0) FROM pos_sales_order_items WHERE order_id=?');$s->execute([$id]);$total=$s->fetchColumn();$this->pdo->prepare('UPDATE pos_sales_orders SET customer_name=?,customer_phone=?,note=?,total_amount=?,version=version+1 WHERE id=?')->execute([trim((string)($p['customer_name']??'')),trim((string)($p['customer_phone']??'')),trim((string)($p['note']??'')),$total,$id]);return['id'=>$id];
    }
    private function orderAction(array$actor,array$p,string$kind):array
