        if($order['status']!=='confirmed'||$this->one('SELECT id FROM pos_sales_returns WHERE order_id=? LIMIT 1',[$id]))throw new RuntimeException('INVALID_ORDER_STATE');$reason=trim((string)($p['reason']??''));if($reason===''||mb_strlen($reason)>1000||!in_array($p['refund_method']??'',['cash','transfer'],true))throw new RuntimeException('VALIDATION_ERROR');foreach($items as$item)$this->moveStock($item['product_id'],(int)$item['quantity'],'cancel',$actor['id'],null,$item['id'],null);$this->pdo->prepare("UPDATE pos_sales_orders SET status='cancelled',cancelled_at=NOW(),cancel_reason=?,cancel_refund_method=?,version=version+1 WHERE id=?")->execute([$reason,$p['refund_method'],$id]);return['id'=>$id];
    }
    private function returnOrder(array$actor,array$p):array
    {
        $id=(string)($p['id']??'');$order=$this->one('SELECT * FROM pos_sales_orders WHERE id=? FOR UPDATE',[$id]);if(!$order||!in_array($order['status'],['confirmed','partially_returned'],true))throw new RuntimeException('INVALID_ORDER_STATE');$items=$p['items']??[];$reason=trim((string)($p['reason']??''));if(!is_array($items)||!$items||count($items)>100||$reason===''||!in_array($p['refund_method']??'',['cash','transfer'],true))throw new RuntimeException('VALIDATION_ERROR');$returnId=self::uuid();$this->pdo->prepare('INSERT INTO pos_sales_returns(id,order_id,reason,refund_method,created_by) VALUES(?,?,?,?,?)')->execute([$returnId,$id,$reason,$p['refund_method'],$actor['id']]);foreach($items as$item){$line=$this->one('SELECT * FROM pos_sales_order_items WHERE id=? AND order_id=? FOR UPDATE',[(string)($item['order_item_id']??''),$id]);if(!$line)throw new RuntimeException('VALIDATION_ERROR');$quantity=(int)($item['quantity']??0);$restock=(int)($item['restock_quantity']??0);if($quantity<1||$restock<0||$restock>$quantity)throw new RuntimeException('VALIDATION_ERROR');$s=$this->pdo->prepare('SELECT COALESCE(SUM(quantity),0) FROM pos_sales_return_items WHERE order_item_id=?');$s->execute([$line['id']]);if($quantity+(int)$s->fetchColumn()>(int)$line['quantity'])throw new RuntimeException('RETURN_EXCEEDS_SOLD');$returnItem=self::uuid();$this->pdo->prepare('INSERT INTO pos_sales_return_items(id,return_id,order_item_id,quantity,restock_quantity,refund_amount) VALUES(?,?,?,?,?,? * ?)')->execute([$returnItem,$returnId,$line['id'],$quantity,$restock,$quantity,$line['unit_sale_price']]);if($restock)$this->moveStock($line['product_id'],$restock,'return',$actor['id'],null,null,$returnItem);}$s=$this->pdo->prepare('SELECT COALESCE(SUM(refund_amount),0) FROM pos_sales_return_items WHERE return_id=?');$s->execute([$returnId]);$refund=$s->fetchColumn();$this->pdo->prepare('UPDATE pos_sales_returns SET refund_amount=? WHERE id=?')->execute([$refund,$returnId]);$sold=$this->scalar('SELEC