    }
    private function saveProduct(array$actor,array$p):array
    {
        $sku=mb_strtoupper(trim((string)($p['sku']??'')),'UTF-8');$name=trim((string)($p['name']??''));$sale=(string)($p['sale_price']??'');$cost=(string)($p['fixed_cost']??'');if($sku===''||mb_strlen($sku)>50||$name===''||mb_strlen($name)>200||!preg_match('/^[0-9]{1,15}$/',$sale)||!preg_match('/^[0-9]{1,15}$/',$cost)||!in_array($p['glass_type']??'',['clear','privacy','matte','other'],true))throw new RuntimeException('VALIDATION_ERROR');$id=$p['id']??null;$models=array_values(array_unique(array_filter(array_map('trim',is_array($p['models']??null)?$p['models']:[]))));
