        $product=$this->one('SELECT * FROM pos_products WHERE id=? FOR UPDATE',[$id]);if(!$product||(int)$product['version']!==(int)($p['version']??0))throw new RuntimeException('VERSION_CONFLICT');if($product['sku']!==$sku&&($this->one('SELECT id FROM pos_inventory_movements WHERE product_id=? LIMIT 1',[$id])||$this->one('SELECT id FROM pos_sales_order_items WHERE product_id=? LIMIT 1',[$id])))throw new RuntimeException('SKU_IMMUTABLE');$priceChanged=$product['sale_price']!==$sale?1:0;$this->pdo->prepare('UPDATE pos_products SET sku=?,name=?,glass_type=?,models=?,brand=?,glass_brand_id=?,image_path=?,sale_price=?,price_version=price_version+?,active=?,version=version+1 WHERE id=?')->execute([$sku,$name,$p['glass_type'],json_encode($models,JSON_UNESCAPED_UNICODE),trim((string)($p['brand']??'other')),$p['glass_brand_id']?:null,$p['image_path']??null,$sale,$priceChanged,(int)!empty($p['active']),$id]);$this->pdo->prepare('UPDATE pos_product_costs SET fixed_cost=? WHERE product_id=?')->execute([$cost,$id]);return['id'=>$id];
    }
    private function inventory(array$actor,array$p):array
    {
        $type=(string)($p['type']??'');$reason=trim((string)($p['reason']??''));$items=$p['items']??[];if(!in_array($type,['opening','receipt','issue','damage','adjustment'],true)||$reason===''||mb_strlen($reason)>1000||!is_array($items)||!$items||count($items)>100)throw new RuntimeException('VALIDATION_ERROR');$documentId=self::uuid();$this->pdo->prepare('INSERT INTO pos_inventory_documents(id,type,reason,created_by) VALUES(?,?,?,?)')->execute([$documentId,$type,$reason,$actor['id']]);foreach($items as$item){$pid=(string)($item['product_id']??'');$quantity=(int)($item['quantity']??-1);if($quantity>1000000||($type!=='adjustment'&&$quantity<=0)||($type==='adjustment'&&$quantity<0))throw new RuntimeException('VALIDATION_ERROR');$product=$this->one('SELECT * FROM pos_products WHERE id=? FOR SHARE',[$pid]);$cost=$this->one('SELECT fixed_cost FROM pos_product_costs WHERE product_id=? FOR SHARE',[$pid]);$balance=$this->one('SELECT * FROM pos_inventory_balances WHERE product_id=? FOR UPDATE',[$pid]);if(!$product||!$cost||!$balance)throw new RuntimeException('PRODUCT_NOT_FOUND');if($type==='opening'&&$this->one('SELECT id FROM pos_inventory_movements WHERE product_id=? LIMIT 1',[$pid]))throw new RuntimeException('OPENING_EXISTS');if($type==='adjustment'&&(int)$balance['version']!==(int)($item['stock_version']??0))throw new RuntimeException('VERSION_CONFLICT');$delta=$type==='adjustment'?$quantity-(int)$balance['on_hand']:(in_array($type,['issue','damage'],true)?-$quantity:$quantity);if($delta===0)continue;$purchase=$item['purchase_price']??null;if($type==='receipt'&&!preg_match('/^[0-9]{1,15}$/',(string)$purchase))throw new RuntimeException('VALIDATION_ERROR');$lineId=self::uuid();$this->pdo->prepare('INSERT INTO pos_inventory_document_items(id,document_id,product_id,quantity_delta,unit_purchase_price,fixed_cost_snapshot,sku_snapshot,name_snapshot) VALUES(?,?,?,?,?,?,?,?)')->execute([$lineId,$documentId,$pid,$delta,$purchase,$cost['fixed_cost'],$product['sku'],$product['name']]);$this->moveStock($pid,$delta,$type,$actor['id'],$lineId,null,null);}return['id'=>$documentId];
    }
    private function exchange(array$actor,array$p):array{$returnId=(string)($p['return_id']??'');if(!$this->one('SELECT id FROM pos_sales_returns WHERE id=? FOR UPDATE',[$returnId]))throw new RuntimeException('VALIDATION_ERROR');$order=$this->one('SELECT id FROM pos_sales_orders WHERE exchange_return_id=?',[$returnId]);if($order)return['id'=>$order['id']];$id=self::uuid();$this->pdo->prepare('INSERT INTO pos_sales_orders(id,created_by,exchange_return_id,note) VALUES(?,?,?,?)')->execute([$id,$actor['id'],$returnId,'Đổi hàng từ phiếu trả '.$returnId]);return['id'=>$id];}
    private function glassBrand(array$actor,array$p):array{$name=trim((string)($p['name']??''));if($name===''||mb_strlen($name)>100)throw new RuntimeException('VALIDATION_ERROR');$id=self::uuid();$this->pdo->prepare('INSERT INTO pos_glass_brands(id,name) VALUES(?,?)')->execute([$id,preg_replace('/\s+/u',' ',$name)]);return['id'=>$id];}
    private function staffState(array$actor,array$p):array{$id=(string)($p['id']??'');$user=$this->one("SELECT * FROM pos_users WHERE id=? AND role='staff' AND deleted_at IS NULL FOR UPDATE",[$id]);if(!$user)throw new RuntimeException('FORBIDDEN');$active=array_key_exists('active',$p)?(int)(bool)$p['active']:(int)$user['active'];$name=array_key_exists('display_name',$p)?trim((string)$p['display_name']):$user['display_name'];if($name===''||mb_strlen($name)>100)throw new RuntimeException('VALIDATION_ERROR');$this->pdo->prepare('UPDATE pos_users SET active=?,display_name=? WHERE id=?')->execute([$active,$name,$id]);if(!$active)$this->pdo->prepare('DELETE FROM pos_sessions WHERE user_id=?')->execute([$id]);return['id'=>$id];}
    private function moveStock(string$productId,int$quantity,string$type,string$actorId,?string$documentItem,?string$saleItem,?string$returnItem):void{$balance=$this->one('SELECT * FROM pos_inventory_balances WHERE product_id=? FOR UPDATE',[$productId]);if(!$balance||(int)$balance['on_hand']+$quantity<0)throw new RuntimeException('INSUFFICIENT_STOCK');$after=(int)$balance['on_hand']+$quantity;$version=(int)$balance['version']+1;$this->pdo->prepare('UPDATE pos_inventory_balances SET on_hand=?,version=? WHERE product_id=?')->execute([$after,$version,$productId]);$this->pdo->prepare('INSERT INTO pos_inventory_movements(id,product_id,movement_type,quantity_delta,balance_after,product_version_after,inventory_document_item_id,sale_order_item_id,return_item_id,actor_id) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([self::uuid(),$productId,$type,$quantity,$after,$version,$documentItem,$saleItem,$returnItem,$actorId]);}
    private function audit(string$actor,string$action,string$detail):void{$this->pdo->prepare('INSERT INTO pos_audit_logs(id,actor_id,action,detail) VALUES(?,?,?,?)')->execute([self::uuid(),$actor,$action,$detail]);}
    private function one(string$sql,array$values=[]):array|false{$s=$this->pdo->prepare($sql);$s->execute($values);return$s->fetch();}
    private function all(string$sql,array$values=[]):array{$s=$this->pdo->prepare($sql);$s->execute($values);return$s->fetchAll();}
